using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CheckReverseDependencies {public static string Main(){EditorApplication.delayCall+=()=>{try{var baseline=new Dictionary<string,(Vector3 p,float support)>();string Key(Collider c)=>c.name+":"+c.transform.position.ToString("F3");bool Local(Collider c){var p=c.bounds.center;return p.x>150&&p.x<450&&p.z>-115&&p.z<115&&!c.isTrigger&&!c.name.StartsWith("Ground_")&&!c.GetComponentInParent<ArcadeVehicle>();}float Ground(Vector3 p)=>Racer.Editor.BackyardReverseAuthoring.Ground(p);
EditorSceneManager.OpenScene("Assets/Scenes/ReverseCorrectionBaseline.unity");Physics.SyncTransforms();foreach(var c in Object.FindObjectsByType<Collider>().Where(Local)){var p=c.bounds.center;p.y=c.bounds.min.y;baseline[Key(c)]=(p,Ground(p));}
EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var rows=new List<string>();foreach(var c in Object.FindObjectsByType<Collider>().Where(Local)){if(!baseline.TryGetValue(Key(c),out var old))continue;float delta=Ground(old.p)-old.support;if(Mathf.Abs(delta)>.025f)rows.Add(c.name+" p="+old.p+" groundDelta="+delta+" oldFootGap="+(old.p.y-old.support));}File.WriteAllLines("Docs/BackyardReverseCorrections/dependency-deltas.txt",rows);File.WriteAllText("Docs/BackyardReverseCorrections/dependency-count.txt",baseline.Count+" existing collider supports compared");}catch(Exception e){File.WriteAllText("Docs/BackyardReverseCorrections/dependency-error.txt",e.ToString());}};return "Compare supporting ground beneath existing local objects with safety checkpoint";}}
